using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GiovanniPascoli
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi ha toccato una volta un'ingiuria – di sangue e di morte – non cesserà mai di toccarne di nuove. Piove sul bagnato: lagrime su sangue, e sangue su lagrime.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Conoscere e descrivere la mente di Dante sarà mai possibile? Egli eclissa nella profondità del suo pensiero: volontariamente eclissa.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Delle città dove sono stato, Matera è quella che mi sorride di più, quella che vedo meglio ancora, attraverso un velo di poesia e di malinconia.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Di quercia caduta ognuno viene a far legna. E tagliato l'albero, così grande e bello, perché hanno a sopravvivere i novelli?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Egli sembra, anche nell'aspetto, una di quelle foreste sul lido del suo mare, le quali anche nella più quieta serenità pare che si contorcano alle raffiche del libeccio.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il paese non è grande, ma nemmeno piccolo; l'aria ottima; pittoreschi i dintorni: le rovine di Grumentum a pochi passi; arpeggiamenti per tutto, che fanno di Viggiano l'Antissa della Lucania.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Questo è il luogo dove si stringono due mani invisibili. È lo stretto e, mi si perdoni il bisticcio, la stretta. Qui la penisola si tende verso l'isola col suo selvoso Aspromonte; qui la Sicilia si protende verso l'Italia col suo candido Faro. La Calabria e la regione Mamertina sono le due mani, che l'Italia e la Sicilia si stringono: sono, se volete meglio, le due labbra con le quali si danno un bacio d'amore indissolubile.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Compagni! Fratelli! Ecco quello che ho a dirvi; a dirvi, non in mio nome soltanto, ma per tutti quelli che voi aveste compagni nell'Università, per quelli che studiavano e lettere e leggi e scienze. Noi vedevamo voi, dopo appena alcuni mesi di allegra spensieratezza, divenir gravi, severi, meditabondi. Da un momento all'altro sembrava che la cara giovinezza si fosse involata dai vostri occhi ventenni. Era che codesti occhi avevano letto la prima pagina del libro. La prima pagina del vostro libro tiene impressa la morte. La serietà suprema del vostro còmpito nella vita vi appariva d'un tratto col suo carattere sacro. Vi si dava a leggere il cadavere nudo dell'uomo, perché vi studiaste il segreto della vita. Non a pascere, ad abbellire ad arricchire la vita vostra, sentivate che gli studi intrapresi dovevano principalmente giovare; ma a custodire, difendere, rivocare la vita degli altri. Vi accorgevate che a voi si chiedeva ben più di quel che si prometteva.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io sono un testimone; e ai testimoni non si chiede altezza d'ingegno e abbondanza di dottrina: si chiede se ha veduto e sa.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Donde venite o uomini? venite da un mondo ben reale, o compagni miei! Venite da tutte le miserie umane, che voi cercate di prevenire, di curare, di lenire almeno, tutte, negli altri, essendo destinati assai spesso a soffocare in voi la peggiore: l'umana ingratitudine. Mal retribuiti, assai spesso, mal conosciuti, sorvegliati, cinti di divieti, irretiti di sofismi, soffocati di diffidenze, da persone che interpretano come \"servizio\" di schiavi un'arte esercitata liberalmente a loro profitto, fischiati (s'è vista anche questa!), ingiuriati, persino espulsi, da gente che profittava delle nuove libertà contro i benefattori del presente e apostoli dell'avvenire.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Voi conoscete i mali inseparabili dalla natura umana, eppure sovrumani sforzi fate contro essi. Più facile opera, anzi gioconda e felice parrebbe dovesse essere quella diretta contro i mali non necessari, non naturali, non umani. Eppure gli uomini si trascinano dietro ancora, dopo millenni e millenni, questa ingrata compagnia che non chiede se non d'essere lasciata nel cammino. Ma voi, o buoni, o forti, o soccorrevoli, come combattete il morbo, come attenuate lo spasimo, come allontanate la morte, così predicate la giustizia, la tolleranza, la pietà.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al mio cantuccio, donde non sento | se non le reste brusir del grano | il suon dell'ore viene col vento | dal non veduto borgo montano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Che torbida notte di marzo! | Ma che mattinata tranquilla! | che cielo pulito! Che sfarzo | di perle! Ogni stelo, una stilla | che ride: sorriso che brilla | su lunghe parole.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Egli coglieva ed ammucchiava al suolo | secche le foglie del suo marzo primo | (era il suo nuovo marzo), il rosignolo, || per farsi il nido. E gorgheggiava in tanto | tutto il gran giorno; e dolce più del timo | e più puro dell'acqua era il suo canto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io sono una lampada ch'arda | soave! | La lampada, forse, che guarda, | pendendo alla fumida trave, | la veglia che fila; || e ascolta novelle e ragioni | da bocche | celate nell'ombra, ai cantoni, | da dietro le soffici ròcche | che albeggiano in fila.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Per le faggete e l'abetine, | dalle fratte e dal ruscello, | quel canto suona senza fine, | chiaro come un campanello. | Per l'abetine e le faggete | canta, ogni ora ogni dì più, | la cinciallegra e ti ripete: | tient'a su! tient'a su! tient'a su!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La Chioccetta per l'aia azzurra | va col suo pigolio di stelle.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La vergine dorme. Ma lenta | la fiamma del puro alabastro | le immemori palpebre tenta; | bussa alla chiusa anima", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Lascia che guardi dentro al mio cuore | lascia ch'io viva del mio passato; | se c'è sul bronco sempre quel fiore, | s'io trovi un bacio che non ho dato! | Nel mio cantuccio d'ombra romita | lascia ch'io pianga sulla mia vita!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Mentre pensavo, e già sentìa, sul ciglio | del fosso, nella siepe, oltre un filare | di viti, dietro un grande olmo, un bisbiglio | truce, un lampo, uno scoppio... ecco scoppiare | e brillare, cadere, esser caduto, | dall'infinito tremolìo stellare, | un globo d'oro, che si tuffò muto | nelle campagne, come in nebbie vane, | vano; ed illuminò nel suo minuto | siepi, solchi, capanne, e le fiumane | erranti al buio, e gruppi di foreste, | e bianchi ammassi di città lontane. | Gridai, rapito sopra me: Vedeste? | Ma non v'era che il cielo alto e sereno. | Non ombra d'uomo, non rumor di péste. | Cielo, e non altro: il cupo cielo, pieno | di grandi stelle; il cielo, in cui sommerso | mi parve quanto mi parea terreno.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nascondi le cose lontane, | tu nebbia impalpabile e scialba, | tu fumo che ancora rampolli, | su l'alba, | da' lampi notturni e da' crolli | d'aeree frane!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Oh! Valentino vestito di nuovo, | come le brocche dei biancospini! | Solo, ai piedini provati dal rovo | porti la pelle de' tuoi piedini || Porti le scarpe che mamma ti fece, | che non mutasti mai da quel dì, | che non costarono un picciolo: in vece | costa il vestito che ti cucì", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il mare è affaticato dall'ansia della vita, e si copre di bianche spume, e rantola sulla spiaggia. Ma tra un'ondata e l'altra suonano le note dell'usignuolo ora singultite come un lamento, ora spicciolate come un giubilo, ora punteggiate come una domanda. L'usignuolo è piccolo, e il mare è grande; e l'uno è giovane, e l'altro è vecchio.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Non l'età grave impedisce di udire la vocina del bimbo interiore, anzi invita forse e aiuta, mancando l'altro chiasso intorno, ad ascoltarla nella penombra dell'anima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "C'è dunque chi non ha sentito mai nulla di tutto questo? Forse il fanciullo tace in voi, professore, perché voi avete troppo cipiglio, e voi non lo udite, o banchiere, tra il vostro invisibile e assiduo conteggio. Fa il broncio in te, o contadino, che zappi e vanghi, e non ti puoi fermare a guardare un poco; dorme coi pugni chiusi in te, operaio, che devi stare chiuso tutto il giorno nell'officina piena di fracasso e senza sole. Ma in tutti è, voglio credere. Siano gli operai, i contadini, i banchieri, i professori in una chiesa a una funzione di festa; si trovino poveri e ricchi, gli esasperati e gli annoiati, in un teatro a una bella musica: ecco tutti i loro fanciullini alla finestra dell'anima, illuminati da un sorriso o aspersi d'una lagrima che brillano negli occhi de' loro ospiti inconsapevoli; eccoli i fanciullini che si riconoscono, dall'impannata al balcone dei loro tuguri e palazzi, contemplando un ricordo e un sogno comune.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Tu sei ancora in presenza del mondo novello, e adoperi a significarlo la novella parola. Il mondo nasce per ognun che nasce al mondo. E in ciò è il mistero della tua essenza e della tua funzione. Tu sei antichissimo, o fanciullo! E vecchissimo è il mondo che tu vedi nuovamente!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "A te né le gemme né gli ori | fornisco, o dolce ospite: è vero; | ma fo che ti bastino i fiori | che cogli nel verde sentiero, | nel muro, su le umide crepe, | su l'ispida siepe.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "altro è sentimento poetico, altro è fantasia; la quale può essere bensì mossa e animata da quel sentimento, ma può anche non essere. Poesia è trovare nelle cose, come ho a dire? il loro sorriso e la loro lacrima; e ciò si fa da due occhi infantili che guardano semplicemente e serenamente di tra l'oscuro tumulto della nostra anima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "la poesia, non ad altro intonata che a poesia, è quella che migliora e rigenera l'umanità, escludendone, non di proposito il male, ma naturalmente l'impoetico.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poeta, se è e quando è veramente poeta, cioè tale che significhi solo ciò che il fanciullo detta dentro, riesce perciò ispiratore di buoni e civili costumi, d'amor patrio e familiare e umano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poeta è poeta, non oratore o predicatore, non filosofo, non istorico, non maestro, non tribuno o demagogo, non uomo di stato o di corte. E nemmeno è, sia con pace del maestro, un artiere che foggi spada e scudi e vomeri; e nemmeno, con pace di tanti altri, un artista che nielli e ceselli l'oro che altri gli porga. A costituire il poeta vale infinitamente più il suo sentimento e la sua visione, che il modo col quale agli altri trasmette l'uno e l'altra.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poeta è colui che esprime la parola che tutti avevano sulle labbra e che nessuno avrebbe detta. Ma non è lui che sale su una sedia o su un tavolo, ad arringare. Egli non trascina, ma è trascinato; non persuade, ma è persuaso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "In verità la poesia è tal meraviglia che se voi fate ora una vera poesia, ella sarà della stessa qualità che una vera poesia di quattromila anni sono. Come mai? Così: l'uomo impara a parlare tanto diverso o tanto meglio, di anno in anno, di secolo in secolo, di millennio in millennio; ma comincia con far gli stessi vagiti e guaiti in tutti i tempi e luoghi. La sostanza psichica è uguale nei fanciulli di tutti i popoli. Un fanciullo è fanciullo allo stesso modo da per tutto. E quindi, né c'è poesia arcadica, romantica, classica, né poesia italiana, greca, sanscrita; ma poesia soltanto, soltanto poesia, e... non poesia. Sì: c'è la contraffazione, la sofisticazione, l'imitazione della poesia, e codesta ha tanti nomi.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Qualunque soggetto può essere contemplato, dagli occhi profondi del fanciullo interiore: qualunque tenue cosa può a quelli occhi parere grandissima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia non si evolve e involve, non cresce o diminuisce; è una luce o un fuoco che è sempre quella luce e quel fuoco: i quali, quando appariscono, illuminano e scaldano ora come una volta, e in quel modo stesso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia benefica di per sé, la poesia che di per sé ci fa meglio amare la patria, la famiglia, l'umanità, è, dunque, la poesia pura, la quale di rado si trova.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ma noi italiani siamo, in fondo, troppo seri e furbi, per essere poeti. Noi imitiamo troppo. E sì, che studiando si deve imparare a far diverso, non lo stesso. Ma noi vogliamo far lo stesso e dare a credere o darci a credere di fare meglio. Perciò sovente ci pare che, incastonando la gemma altrui in un anello nostro, noi abbiamo trovata e magari fatta la gemma; e più sovente ci immaginiamo che, dorando la statua di bronzo, quella statua non solo sia più bella, ma diventi opera nostra.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La poesia consiste nella visione d'un particolare inavvertito, fuori e dentro di noi.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Oh! come è necessaria l'imperfezione per essere perfetti!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Gli occhi della gente sono oggi così fissi nell'ombelico della propria persona, che non hanno visto, si può dire, altro.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ricòrdati che la poesia vera fa battere, se mai, il cuore, non mai le mani.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "questo oblìo che preme subito i morti, non è, quanto ai letterati, senza ragione e senza giustizia. Noi letterati vogliamo in vita occupar troppo il mondo di noi. Se stessimo nel nostro angolo, se non ci sbracciassimo tanto nel mezzo della gente, se non vociassimo tanto, non avverrebbe questo compenso di silenzio dopo morte.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "A ogni modo perché dovrebbe essere altrimenti? Che cosa fai tu, veramente, che sia degno di lode e di gloria? Tu ridi, tu piangi: che merito in ciò? Se credi d'averci merito, è segno che ridi e piangi apposta: se lo fai apposta, non è poesia la tua: se non è poesia, non hai diritto a lode. Tu scopri, s'è detto; non inventi: e ciò che scopri, c'era prima di te e ci sarà senza te. Vorresti scriverci il tuo nome su? Ti adiri, che ti vogliano giudicare e anche premiare per quello che non è se non la tua natura e la tua manifestazione di vita. Dunque che importa a te del nome?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Voglio la vita mia lasciar, pendula | ad ogni stelo, sopra ogni petalo, | come una rugiada | ch'esali dal sonno, e ricada || nella nostr'alba breve. Con l'iridi | di mille stille sue nel sole unico | s'annulla e sublima... | lasciando più vita di prima.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "I poeti hanno abbellito agli occhi, alla memoria, al pensiero degli uomini, la terra, il mare, il cielo, l'amore, il dolore, la virtù; e gli uomini non sanno il loro nome.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sonno è la vita quando è già vissuta: | sonno; chè ciò che non è tutto, è nulla. | Io, desto alfine nella patria terra, | ero com'uomo che nella novella | alba sognò, né sa qual sogno, e pensa | che molto è dolce a ripensar qual era. | Or io mi voglio rituffar nel sonno, | s'io trovi in fondo dell'oblio quel sogno.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E non vide la casa, né i leoni | dormir col muso su le lunghe zampe, | né la sua dea. Ma declinava il sole, | e tutte già s'ombravano le strade.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E il vecchio vide che le due Sirene, | le ciglia alzate sulle due pupille, | avanti se miravano, nel sole | fisse, od in lui, nella sua nave nera. | E su la calma immobile del mare, | alta e sicura egli inalzò la voce. | \"Son io! Son io, che torno per sapere! | Che molto io vidi, come voi vedete | me. Sì; ma tutto ch'io guardai nel mondo, | mi riguardò; mi domandò: Chi sono?\"", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ed ecco Calipso usciva con la spola in mano, | d'oro, e guardò. Giaceva in terra, fuori | del mare, al piè della spelonca, un uomo, | sommosso ancor dall'ultima onda: e il bianco | capo accennava di saper quell'antro, | tremando un poco; e sopra l'uomo un tralcio | pendea con lunghi grappoli dell'uve. | Era Odisseo: lo riportava il mare | alla sua dea: lo riportava morto | alla Nasconditrice solitaria, | all'isola deserta che frondeggia | nell'ombelico dell'eterno mare. | Nudo tornava chi rigò di pianto | le vesti eterne che la dea gli dava.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sempre un villaggio, sempre una campagna | mi ride al cuore (o piange), Severino: | il paese ove, andando, ci accompagna | l'azzurra visïon di San Marino: | sempre mi torna al cuore il mio paese | cui regnarono Guidi e Malatesta, | cui tenne pure il Passator cortese, | re della strada, re della foresta", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Da' borghi sparsi le campane in tanto | si rincorron coi lor gridi argentini: | chiamano al rezzo, alla quiete, al santo | desco fiorito d'occhi di bambini.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Dal profondo geme l'organo | tra 'l fumar de' cerei lento: | c'è un brusio cupo di femmine | nella chiesa del convento: || un vegliardo austero mormora | dall'altar suoi brevi appelli: | dietro questi s'acciabattano | delle donne i ritornelli. || [...] || \"Per noi prega, o santa Vergine, | per noi prega, o Madre pia; | per noi prega, esse ripetono, | o Maria! Maria! Maria!\"", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al camino, ove scoppia la mortella | tra la stipa, o ch'io sogno, o veglio teco: | mangio teco radicchio e pimpinella", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Al rio sottile, di tra vaghe brume, | guarda il bove coi grandi occhi: nel piano | che fugge, a un mare sempre più lontano | migrano l'acque d'un ceruleo fiume.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "San Lorenzo, io lo so perché tanto | di stelle per l'aria tranquilla | arde e cade, perché sì gran pianto | nel concavo cielo sfavilla", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E tu, Cielo, dall'alto dei mondi | sereni, infinito, immortale, | oh! d'un pianto di stelle lo inondi | quest'atomo opaco del Male", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E cielo e terra si mostrò qual era: || la terra ansante, livida, in sussulto; | il cielo ingombro, tragico, disfatto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io la felicità inseguo per monti, per piani, | pel mare, pel cielo, nel cuore, | io la vedo, già tendo le mani, | già tengo la gloria e l'amore", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Quando brillava il vespero vermiglio, | e il cipresso pareva oro, oro fino, | la madre disse al piccoletto figlio: | Così fatto è lassù tutto un giardino. | Il bimbo dorme e sogna i rami d'oro, | gli alberi d'oro, le foreste d'oro; | mentre il cipresso nella notte nera | scagliasi al vento, piange alla bufera.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Stavano neri al lume della luna | gli erti cipressi, guglie di basalto, | quando tra l'ombre svolò rapida una | ombra dall'alto: | orma sognata d'un volar di piume, | orma d'un soffio molle di velluto, | che passò l'ombre e scivolò nel lume | pallido e muto: | ed i cipressi sul deserto lido | stavano come un nero colonnato, | rigidi, ognuno con tra i rami un nido | addormentato.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Udia tra i fieni allor allor falciati | de' grilli il verso che perpetuo trema, | udiva dalle rane dei fossati | un lungo interminabile poema", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sembra un vociare, per la calma, fioco, | di marinai, ch'ad ora ad ora giunga | tra 'l fievole sciacquio della risacca", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Scendea tra gli olmi il sole | in fascie polverose; | erano in ciel due sole | nuvole, tenui, róse: | due bianche spennellate | in tutto il ciel turchino. | Siepi di melograno, | fratte di tamerice, | il palpito lontano | d'una trebbïatrice, | l'angelus argentino...", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Manina chiusa, che nel sonno grande | stringi qualcosa, dimmi cosa ci hai! | Cosa ci ha? cosa ci ha? Vane domande: | quello che stringe, niuno saprà mai", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Come un'arca d'aromi oltremarini, | il santuario, a mezzo la scogliera, | esala ancora l'inno e la preghiera | tra i lunghi intercolunnii de' pini", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Allora... io un tempo assai lunge | felice fui molto; non ora: | ma quanta dolcezza mi giunge | da tanta dolcezza d'allora!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nel campo mezzo grigio e mezzo nero | resta un aratro senza buoi, che pare | dimenticato, tra il vapor leggero.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nella soffitta è solo, è nudo, muore. | Stille su stille gemono dal tetto || [...] || La notte cade, l'ombra si fa nera; | egli va, desolato, in Paradiso.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Più bello il fiore cui la pioggia estiva | lascia una stilla dove il sol si frange.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Noi mentre il mondo va per la sua strada, | noi ci rodiamo, e in cuor doppio è l'affanno, | e perché vada, e perché lento vada.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Odi, sorella, come note al core | quelle nel vespro tinnule campane | empiono l'aria quasi di sonore | grida lontane?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Quanti quel roseo campanile bisbigli | udì, quel giorno, o strilli di rondoni | impazienti agl'inquieti figli", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Rosa di macchia, che dall'irta rama | ridi non vista a quella montanina, | che stornellando passa e che ti chiama | rosa canina", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Sappi – e forse lo sai, nel camposanto – | la bimba dalle lunghe anella d'oro, | e l'altra che fu l'ultimo tuo pianto, | sappi ch'io le raccolsi e che le adoro.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Vien per la strada un povero che il lento | passo tra foglie stridule trascina: | nei campi intuona una fanciulla al vento: | Fiore di spina!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Gemmea l'aria, il sole così chiaro | che tu ricerchi gli albicocchi in fiore, e del biancospino l'odorino amaro | senti nel cuore... || Ma secco è il pruno, e le stecchite piante | di nere trame segnano il sereno, | e vuoto il cielo, e cavo al piè sonante | sembra il terreno || Silenzio, intorno: solo, alle ventate, | odi lontano, da giardini ed orti, | di foglie un cader fragile. È l'estate, | dei morti.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Anch'io; ricordo, ma passò stagione; | quelle bacche a gli uccelli della frasca | invidiavo, e le purpuree more; | e l'ala, i cieli, i boschi, la canzone: | i boschi antichi, ove una foglia casca, | muta, per ogni battito di cuore", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E nella notte nera come il nulla, || a un tratto, col fragor d'arduo dirupo | che frana, il tuono rimbombò di schianto: | rimbombò, rimbalzò, rotolò cupo, | e tacque, e poi rimareggiò rinfranto, | e poi vanì. Soave allora un canto | s'udì, di madre, e il moto di una culla.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Per te i tuguri sentono il tumulto | or del paiolo che inquïeto oscilla; | per te la fiamma sotto quel singulto crepita e brilla; || tu, pio castagno, solo tu, l'assai | doni al villano che non ha che il sole; | tu solo il chicco, il buon di più, tu dài alla sua prole; || ha da te la sua bruna vaccherella | tiepido il letto e non desìa la stoppia; | ha da te l'avo tremulo la bella fiamma che scoppia. || Scoppia con gioia stridula la scorza | de' rami tuoi, co' frutti tuoi la grata | pentola brontola.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Mettea, chi fiori non potea, le spine; | mettea le gemme l'albero più brullo: | piovea la quercia, vergognando alfine, | le vecchie foglie a' piedi del fanciullo.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Le voci fuori ne traea più belle | e più lontane. Ed ecco che su l'aia | vide due rondini alïare snelle. || Svolar le vide sotto la grondaia, | e poi sparire; e ritornar più tante, | tornare in quattro, in otto, in dieci, a paia. || E stava sotto il prugno tremolante | di bianchi fiori, tra il girar veloce | di tante nere rondinelle sante. || (Avean Gesù pur consolato in croce!) | Forse mancava a casa lor qualcosa: | parlavan alto, tutte ad una voce...", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Avevi i piedi ignudi su la soglia, | tremavi come un armellino in fiore, | che trema tutto al vento che lo spoglia.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ma il torcicollo a cui nulla si cela, | avanti o dietro, e che giammai non erra, | cantava pur la lunga sua querela.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Udiano le due voci delle sere | di primavera, limpide e sonore, | così lontane che parean non vere, || così vicine che parean del cuore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Voi fate troppo, autunno verno estate. | Rosa, se non lavate, voi stendete! | Rosa, se non tessete, voi filate! || Per voi non c'è momento di quiete. | Tutto tenete lindo, netto, asciutto, | lustrate ogni solaio ogni parete. || Parete un uccelletto, biondo, sdutto, | snello, che cala becca salta frulla | in un minuto. E sola fate il tutto!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Allor s'aprì la prima stella in cielo; | e dalla terra tacita e sorpresa | si levò un trillo come un lungo stelo. || Un'altra, un altro. Ad ogni stella accesa, | un nuovo canto. Un canto senza posa | correva ardendo lungo la distesa || del cielo azzurro. – È l'usignolo, o Rosa! –", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il mare, al buio, fu cattivo. Urlava | sotto gli schiocchi della folgore! Ora | qua e là brilla in rosa la sua bava. | Intorno a mucchi d'alga ora si dora | la bava sua lungi da lui. S'effonde | l'alito salso alla novella aurora. | Vengono e vanno in un sussurro l'onde. | Sembra che l'una dopo l'altra salga | per veder meglio. E chiede una, risponde | l'altra, spiando tra quei mucchi d'alga...", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Non siamo onde superbe, onde sommesse. | Onde, e non più. L'acqua del mare è tanta! | Siamo in un attimo, e non mai le stesse. || Ora io son quella che già là s'è franta. | E io già quella ch'ora là si frange. | L'onda che geme ora è lassù, che canta; | l'onda che ride, ai piedi tuoi già piange.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Noi siamo quello che sei tu: non siamo. | L'ombre del moto siamo. E ci son onde | anche tra voi, figli del rosso Adamo? | Non sono. È il vento ch'agita, confonde, | mesce, alza, abbassa; è il vento che ci schiaccia | contro gli scogli e rotola alle sponde.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Andava all'Alpe, dove più non sono | che greggi erranti, e dove non si sente, | fuor che di foglie al vento, altro frastuono; || o il solitario scroscio del torrente | dopo un'acquata, o il conversar tranquillo, | presso le bianche nuvole, di gente, || che non si vede, intorno cui lo squillo | de' campanacci va per le pratina | odorate di menta e di serpillo.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Usignol della nebbia, che i nostri orti | visiti quando non c'è più che bruchi, | tu che ci lodi il verno che ci porti; || e ti fai cuore, e vieni e vai, t'imbuchi, | t'infraschi, e cerchi e fai sentire un canto | appena trovi sanguini o sambuchi:", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "girare i boschi, bere ai puri fonti | della sua terra, e te godere ancora, | sole, che così bello oggi tramonti, || e, dopo ancor l'avemaria, quest'ora | chiara e la sera che s'addorme e pare | sognar, sui monti, d'essere l'aurora.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi vede mai le pratelline in boccia? | Ed un bel dì le pratelline in fiore | empiono il prato e stellano la roccia. || Chi ti sapeva, o bianco fior d'amore | chiuso nel cuore? E tutta, all'improvviso, | la nera terra ecco mutò colore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "O mezzo aperta come chi non osa, | o pratellina pallida e confusa, || che sei dovunque l'occhio mio si posa, | e chini il capo, all'occhio altrui non usa; || bianca, ma i lievi sommoli, di rosa; | tanto più rosa quanto più sei chiusa: || ti chiudi a sera, chi sa mai per cosa, | sei chiusa all'alba, ed il perché sai tu; || o primo amore, o giovinetta sposa, | o prima e sola cara gioventù!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "È il verno, e tutti i fiori arse la brina | nei prati e tutte strinò l'erbe il gelo: | ma te vedo fiorir, primaverina. || Tu persuasa dal fiorir del cielo, | fioristi; ed ora, quasi più non voglia | perché sei sola, appena alzi lo stelo. | O fior d'amore su la trita soglia! | Tu tingi al sommo i petali d'argento | d'un rosso lieve. Una raminga foglia | ti copre un poco, e passa via col vento... || O fior d'amore sulla soglia trita! | o quando tutto se ne va, venuta! | che vivi quando è per finir la vita! | e che non muti anche se il ciel si muta!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ma il frate, andando, con un pio sgomento | toccava appena la rea terra, appena | guardava il folgorìo del firmamento: || quella nebbia di mondi, quella rena | di Soli sparsi intorno alla Polare | dentro la solitudine serena. || Ognun dei Soli nel tranquillo andare | traeva seco i placidi pianeti | come famiglie intorno al focolare: || oh! tutti savi, tutti buoni, queti, | persino ignari, colassù, del male, | che no, non s'ama, anche se niun lo vieti.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "dolore è più dolor, se tace", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi piange in sogno, è giunto a ciò che vuole, | è giunto alfine a tutto ciò che implora | invano.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Or sì, conviene ai gelsi bianchi, ai mori, | dare il pennato, e portar foglia a fasci, | con fruscìo grande e il fresco odor di fuori! || Ma su le prime indugi un po'; né lasci | che il gregge impingui, e se ne perda il frutto: | attenta, accorta, a man a man li pasci | più largamente, fin che indulgi il tutto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Fioria la zucca, arsivano i piselli, | nell'orto. Le ciliege erano andate: | per San Giovanni avevano i giannelli.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E il grano al vento strepitava; e disse | il padre al figlio: \"Mieteremo. Vedi: | verdino è, sì, ma non vorrei patisse. || Ché il grano dice: — Io sto ritto, e tu siedi. | Qui temo l'acqua, e il vento mi dà briga. | Altronde, o presto o tardi, o steso o in piedi, | se il gambo è secco seccherà la spiga —\"", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La terra è buona: dura, ma fedele; | ma è una barca, il sole per timone, | e bianche e nere nuvole per vele. || Ci vuole il cielo: tutto a sua stagione; | e freddo, caldo, dolce, aspro, ci vuole, | e i lampi e tuoni e il fumido acquazzone.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Si sa: marzo va secco, il gran fa cesto. | Il gran, per uno pallido e sottile, | più ciuffi mise, quanto più fu pesto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Chi prega è santo, ma chi fa, più santo", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Né lavorato avevo a fondo: a fondo | avevo sì, ma pel granturco d'anno. | Il grano è meglio, e però vien secondo. || Sta pago il grano a quello che gli dànno. | Vuol sì la terra trita, ma non trita | tanto, che, anzi, gli sarebbe a danno. || Non diedi al grano che mi dà la vita, | nemmeno il concio. Poco o nulla e' chiede | per far la spiga bella e ben granita.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il meglio, il fiore dell'annata intera, | noi manderemo subito al molino; | che l'abbia a giorno e che lo renda a sera.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Nere le mete: solo qualche lampo | facean le paglie, come se un tesoro | fosse disperso qua e là nel campo.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "L'alba sul monte e l'ombra nella valle. | I vermi chiusi ne' ben fatti avelli, | piccole mummie, rinascean farfalle. || Le spose uscian da' bozzoli più belli, | candide e gravi. Col frullar dell'ale | movean ver loro i brevi maschi snelli. || La savia madre il letto nuzïale | bianco lor tese. Ognuno andava in traccia | d'una compagna all'opera immortale.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Va col corredo quale a te perviene. || Frullare il fuso e correre la spola | facesti assai! La tela, che tessesti! | Quante coperte e paia di lenzuola! || Tutte son tue; che, quando là ti desti | nei primi giorni, prima che sia giorno, | pensi che i più, degli anni tuoi, son questi. || Ti sentirai l'odor di casa attorno, | il buon odor di spigo e di cotogno, | e di tua mamma; ed ecco, di ritorno || sarai, tra noi, se dopo dormi, in sogno.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E salutò coi cenni della mano | la vigna verde che le dava il vino, | il campo grande che le dava il grano; || e il melograno rosso e il biancospino | della sua siepe, e il campo così smorto, | in cui fiorì come un bel cielo il lino: || ciò ch'era morto e ciò ch'era risorto, | ciò che nasceva e che moriva al sole, | la selva, il prato, l'oliveta e l'orto.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Che cosa avrebbe egli da lei voluto? | Qual piaga dare tenera e mortale | a quelle carni bianche, di velluto? || Qual pianto fa di quel ch'è ora, e quale | rimpianto mai di quel ch'un giorno fu!... — | Col mesto verso eternamente uguale || le rispondeva di lontano il chiù.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "S'alza a vedere; tra le nubi e i venti | s'adagia in cielo. Nelle valli brune | vede gettarsi i botri ed i torrenti. || Vanno con un feroce urlo comune, | chi qua chi là. Scendono ciechi al piano, | portano massi, travi, alberi, cune. || Hanno la cupa voce d'uragano | e di valanga; ed il fragor con loro | rapido va, ma non è mai lontano. || Fuor dalle nubi, risplendente d'oro, | l'aquila ruota, remeggiando lenta, | sopra il terrestre vortice sonoro. | E s'alza ancora ed alto un grido avventa, | atroce, per le vane plaghe sole. | Tre volte grida, e sta tre volte intenta || all'eco forse che ne mandi il sole.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Voli lo staccio e treppichi giocondo, | vaporando il suo bianco alito fino, | che si depone sul tuo capo biondo. || O lieve staccio, io t'amo. Il tuo destino | somiglia al mio: tener la crusca; il fiore, | spargerlo puro per il tuo cammino. | E fai codesto con un tuo rumore | lieto, in cadenza: semplice, ma bello | per l'orecchio del pio lavoratore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il poco è molto a chi non ha che il poco:", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Ciò che secca e che cade e che s'oblia, | io lo raccolgo: ancora ciò che al cuore | si stacca triste e che poi fa che sia | morbido il sonno, il giorno che si muore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Entra, vegliardo, antico ospite: ed ecco | l'azimo antico degli eroi, che cupi | sedeano all'ombra della nave in secco || (si levarono grandi sulle rupi | l'aquile; e nella macchia era tra i rovi | un inquïeto guaiolar di lupi...): | il pane della povertà, che trovi | tu, reduce aratore, esca veloce, | che sol s'intrise all'apparir dei bovi: || il pane dell'umanità, che cuoce | in mezzo a tutti, sopra l'ara, e intorno | poi si partisce in forma della croce: || il pane della libertà, che il forno | sdegna venale; cui partisci, o padre, | tu, nelle più soavi ore del giorno: || ognuno in cerchio mangia le sue quadre; | più, i più grandi, e assai forse nessuno; |o forse n'ebbe più che assai la madre, || cui n'avanza da darne un po' per uno.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Azimo santo e povero dei mesti | agricoltori, il pane del passaggio | tu sei, che s'accompagna all'erbe agresti; || il pane, che, verrà tempo, e nel raggio | del cielo, sulla terra alma, gli umani | lavoreranno nel calendimaggio.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E la luna calante batté gialla | sull'impannata. Netta, senza brume, | stava, sul liscio mar di neve, a galla. || L'immensa taiga biancheggiava al lume. | Qualche betulla nuda, qualche cono | d'abete, e solchi d'ombra d'un gran fiume.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Fole! | L'uomo non vola, o garrula ghiandaia, | come gli uccelli e come le parole!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io l'ho veduta. | In un suo libro. Egli sapea contare | i monti e i mari. Io l'ascoltava muta. || C'è il Mare di Serenità. C'è il Mare | di Nubi. Anche, di Pioggie e di Tempeste. | Un altro Mare senza l'acque amare. || C'è la Palude delle Nebbie meste. | C'è anche un Seno, a goccia a goccia pieno | di guazza dalla grande alba celeste. || E c'è il Lago dei Sogni. Anche c'è il Seno | delle Iridi: tanti alti archi di porte | nel cielo: un infinito arcobaleno. || Vicino ai Sogni, il Lago della Morte.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "O tacito paese | sopra le nubi! O isola del cielo, | che fiorisci e sfiorisci d'ogni mese!", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "E non c'è dì senz'alba, e l'alba è l'ora | più bella; e senza fiore non c'è frutto, | e il fiore è bello, il fiore è il più che odora.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Io l'ho veduta. Corre sempre, vola, | passa. Ma mentre va, che non mai posa, | a noi non volge che una parte sola. || Vediamo, noi, nel cielo azzurro o rosa, | sempre quelle montagne, sempre quelle | paludi. Sempre. Ma di là? Che cosa | è mai di là, verso le grandi stelle?", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Più che mezza la luna era, e più ore | restava su, tra l'iridato alone, | e le notti imbevea del suo pallore.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Vento dei Santi, il giorno si raccoglie | già per morire; e tu su' due gemelli | alberi soffi, e stacchi lor le foglie. || Ora le tocchi appena, ora le svelli: | quali cadono a una a una, quali | partono a branchi, come vol d'uccelli. || Tutta una fuga, quando tu li assali, | si fa nel cielo, e in terra, fra le zolle, | un fruscìo grande, un vano tremor d'ali: || stridono e vanno, girano in un folle | vortice, frullano inquïete attorno, | calano con un abbandono molle.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Viene col vento un canto di preghiera | e di tristezza, e vanno via le foglie | con lui, stridendo in mezzo alla bufera: || \"Noi di noi siamo le fugaci spoglie: | la nostra vita è sempre là dov'era. || Il vento in vano all'albero ci toglie: | là rinverzicheremo a primavera.\" | Col vento via le vane foglie vanno; | gemono, mentre intorno si fa sera. | \"Non torneremo al rifiorir dell'anno: | noi ce n'andiamo avvolte nell'oblìo. | Non fu la vita che un fugace inganno. | L'albero è morto. Addio per sempre! Addio!\"", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La paradisa ha pigne lunghe e chiare, | e tutti d'oro sono i chicchi, e hanno | il sole dentro, il sole che traspare.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il bello è bello, ma non dura.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "La gente era venuta sull'aurora | quando la guazza o la nebbietta inerte | vapora in cielo, e il cielo si colora.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Il cielo già si colorava in fuoco. | Al colmo tino il giovinetto snello | si lanciò su, come provar per gioco. || Stette sull'orlo un poco in piedi, bello, | raggiante tutto del suo bel domani, | a braccia spante, simile a un uccello. || Poi si chinò, s'apprese con le mani | all'orlo, e dentro, fra le pigne frante | tuffò le gambe e sul crosciar dei grani. || Il rosso mosto risalì spumante | sopra i garretti; ed ei girava a tondo | premendo coi calcagni e con le piante. || E il sole rosso illuminava il biondo | vendemmiatore; ed ecco, da un remoto | canto del cielo un tintinnìo giocondo. || Uno, dal cielo, accompagnava il moto | dei piedi suoi, di su quei rosei fiocchi, | picchiando in furia sur un bronzo vuoto... || L'altro moveva rapidi i ginocchi | sul rosso mosto, anche movea la testa | ben in cadenza, il sole in mezzo agli occhi.", Author = "Giovanni Pascoli" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Pascoli", Text = "Oh! non a nulla! Egli rideva, io penso, | con gli angioletti. Io ci sentii l'odore | di gigli, a volte; o un vago odor d'incenso. || Nella sua stanza essi venian nell'ore | calde che i bimbi dormono. Alla gola | uno lo v", Author = "Giovanni Pascoli" },
        };
    }
}